    static string InlineAesDecrypt(string cipherHex, string keyHex, string ivHex)
    {
        byte[] cipherBytes = HexToBytes(cipherHex);
        byte[] key = HexToBytes(keyHex);
        byte[] iv = HexToBytes(ivHex);

        // 1. AES 복호화를 위한 라운드 키 확장
        byte[] roundKeys = ExpandKey(key);

        // 2. CBC 모드 복호화
        byte[] decrypted = new byte[cipherBytes.Length];
        byte[] prevBlock = new byte[16];
        Array.Copy(iv, prevBlock, 16);

        for (int i = 0; i < cipherBytes.Length; i += 16)
        {
            byte[] block = new byte[16];
            Array.Copy(cipherBytes, i, block, 0, 16);

            DecryptBlock(block, roundKeys); // 블록 복호화

            // CBC XOR 연산
            for (int j = 0; j < 16; j++)
            {
                decrypted[i + j] = (byte)(block[j] ^ prevBlock[j]);
            }

            Array.Copy(cipherBytes, i, prevBlock, 0, 16); // 다음 블록을 위해 현재 암호문 저장
        }

        // 3. PKCS7 패딩 제거
        int padLength = decrypted[decrypted.Length - 1];            
        int actualLength = decrypted.Length - padLength;
        byte[] result = new byte[actualLength];
        Array.Copy(decrypted, result, actualLength);

        return Encoding.UTF8.GetString(result);
    }

    // 16진수 문자열을 바이트로 변환
    static byte[] HexToBytes(string hex)
    {
        byte[] bytes = new byte[hex.Length / 2];
        for (int i = 0; i < hex.Length; i += 2)
            bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
        return bytes;
    }

