    static byte[] ExpandKey(byte[] key)
    {
        int nk = key.Length / 4; // AES-256: 8
        int nr = nk + 6;         // AES-256: 14
        int totalWords = 4 * (nr + 1); // 60 Words
        byte[] w = new byte[4 * totalWords];
        Array.Copy(key, w, key.Length);

        // 🔥 Rcon(Round Constant) 배열 추가 (이전 코드의 오류 수정)
        byte[] rcon = { 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40 };
        byte[] temp = new byte[4];

        for (int i = nk; i < totalWords; i++)
        {
            Array.Copy(w, (i - 1) * 4, temp, 0, 4);

            if (i % nk == 0)
            {
                // RotWord & SubWord
                byte t = temp[0];
                temp[0] = sbox[temp[1]];
                temp[1] = sbox[temp[2]];
                temp[2] = sbox[temp[3]];
                temp[3] = sbox[t];
                // 🔥 XOR with Rcon
                temp[0] ^= rcon[(i / nk) - 1];
            }
            else if (nk > 6 && i % nk == 4)
            {
                // SubWord only
                temp[0] = sbox[temp[0]];
                temp[1] = sbox[temp[1]];
                temp[2] = sbox[temp[2]];
                temp[3] = sbox[temp[3]];
            }

            for (int j = 0; j < 4; j++)
                w[i * 4 + j] = (byte)(w[(i - nk) * 4 + j] ^ temp[j]);
        }
        return w;
    }

    static void DecryptBlock(byte[] state, byte[] roundKeys)
    {
        int nr = (roundKeys.Length / 16) - 1; // 14 rounds
        AddRoundKey(state, roundKeys, nr);

        for (int round = nr - 1; round >= 1; round--)
        {
            InvShiftRows(state);
            InvSubBytes(state);
            AddRoundKey(state, roundKeys, round);
            InvMixColumns(state);
        }

        InvShiftRows(state);
        InvSubBytes(state);
        AddRoundKey(state, roundKeys, 0);
    }

    static void AddRoundKey(byte[] state, byte[] roundKeys, int round)
    {
        for (int i = 0; i < 16; i++)
            state[i] ^= roundKeys[round * 16 + i];
    }

    static void InvSubBytes(byte[] state)
    {
        for (int i = 0; i < 16; i++) state[i] = rsbox[state[i]];
    }

    static void InvShiftRows(byte[] state)
    {
        byte t;
        // Row 1
        t = state[13]; state[13] = state[9]; state[9] = state[5]; state[5] = state[1]; state[1] = t;
        // Row 2
        t = state[2]; state[2] = state[10]; state[10] = t;
        t = state[6]; state[6] = state[14]; state[14] = t;
        // Row 3
        t = state[3]; state[3] = state[7]; state[7] = state[11]; state[11] = state[15]; state[15] = t;
    }

    static void InvMixColumns(byte[] state)
    {
        for (int i = 0; i < 4; i++)
        {
            int c = i * 4;
            byte a0 = state[c], a1 = state[c + 1], a2 = state[c + 2], a3 = state[c + 3];
            state[c] = (byte)(mul(a0, 14) ^ mul(a1, 11) ^ mul(a2, 13) ^ mul(a3, 9));
            state[c + 1] = (byte)(mul(a0, 9) ^ mul(a1, 14) ^ mul(a2, 11) ^ mul(a3, 13));
            state[c + 2] = (byte)(mul(a0, 13) ^ mul(a1, 9) ^ mul(a2, 14) ^ mul(a3, 11));
            state[c + 3] = (byte)(mul(a0, 11) ^ mul(a1, 13) ^ mul(a2, 9) ^ mul(a3, 14));
        }
    }

    static byte mul(byte a, byte b)
    {
        byte p = 0;
        while (b > 0)
        {
            if ((b & 1) != 0) p ^= a;
            bool hiBitSet = (a & 0x80) != 0;
            a <<= 1;
            if (hiBitSet) a ^= 0x1B;
            b >>= 1;
        }
        return p;
    }
